def Spec.tdflite_decision_core.w_released.reading : Prop :=
  Frames.Always ((Tdf.release).given (fun st inp => st = Tdf.twoLevelPolicy ∧ inp = Tdf.clearedDeclaring)) (fun ans => Abac.released ans) ∧
    Frames.Always ((Tdf.release).given (fun st inp => st = Tdf.twoLevelPolicy ∧ inp = Tdf.clearedDeclaring)) (fun ans => Abac.entitled ans)

def Spec.tdflite_decision_core.w_withheld.reading : Prop :=
  Frames.Never ((Tdf.release).given (fun st inp => st = Tdf.twoLevelPolicy ∧ inp = Tdf.clearedSilent)) (fun ans => Abac.released ans) ∧
    Frames.Always ((Tdf.release).given (fun st inp => st = Tdf.twoLevelPolicy ∧ inp = Tdf.clearedSilent)) (fun ans => Abac.entitled ans)
